<?php require __DIR__."/vendor/autoload.php"; $app = require_once __DIR__."/bootstrap/app.php"; $kernel = $app->make(Illuminate\Contracts\Console\Kernel::class); $kernel->bootstrap(); $items = DB::table("category_data_br_buildings")->where("name_en", "like", "%Neelly Star Hotel%")->get(); foreach($items as $item) { echo "Name: {$item->name_en}, Province: {$item->raw_province}, Dist: {$item->raw_district}, DS: {$item->raw_ds}, GN: {$item->raw_gn}\n"; }
